import sys
from itertools import permutations

data = sys.stdin.read().split()
n = int(data[0])
nums = list(map(int, data[1:1 + n]))

def shape(a):
    left, right = {}, {}
    root = a[0]
    for x in a[1:]:
        cur = root
        while True:
            if x < cur:
                if cur in left:
                    cur = left[cur]
                else:
                    left[cur] = x
                    break
            else:
                if cur in right:
                    cur = right[cur]
                else:
                    right[cur] = x
                    break
    return (root, tuple(sorted(left.items())), tuple(sorted(right.items())))

target = shape(nums)
count = 0
for p in permutations(nums):
    if shape(p) == target:
        count += 1
print((count - 1) % (10 ** 9 + 7))

